def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque

    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}

    # Find the main compact, multicolored object; isolated pixels are placement markers.
    comps = []
    unseen = set(cells)
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        comps.append(comp)

    # The test motif is a connected patch of two colors, while the lone 2 is its marker.
    main = max(comps, key=lambda comp: (len(comp), len({grid[r][c] for r,c in comp})))
    rmin = min(r for r,c in main); rmax = max(r for r,c in main)
    cmin = min(c for r,c in main); cmax = max(c for r,c in main)
    ar, ac = (rmin+rmax)//2, (cmin+cmax)//2

    out = [row[:] for row in grid]
    for comp in comps:
        if comp == main:
            continue
        # Place a copy of the motif with its center on the isolated marker.
        for r, c in comp:
            dr, dc = r-ar, c-ac
            for mr, mc in main:
                nr, nc = mr+dr, mc+dc
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = grid[mr][mc]
    return out
